function transitPlan(){if(from.external&&to.external){$('route-result').innerHTML='<div class="notice">لا توجد لدينا رحلة مباشرة موثقة بين وجهتين خارج كيان. افتح دليل الباصات لمراجعة الخطوط.</div>';return;}const external=from.external||to.external;let line=transit.routes.find(r=>r.externalId===external);if(!external)line=transit.routes.find(r=>r.id==='auc');if(!line){$('route-result').innerHTML='<p class=notice>لا يوجد خط منشور لهذه الوجهة حاليًا.</p>';return;}$('bus-line').value=line.id;busDirection=from.external?'in':'out';document.querySelectorAll('[data-direction]').forEach(b=>b.classList.toggle('active',b.dataset.direction===busDirection));renderBus();const options=busOptions(),state=transitState(line,options.date,busDirection,options.dayType);routeLayer.clearLayers();lastRoute=null;
 $('route-result').innerHTML=`<div class="route-card"><div class="route-card-head"><div><strong dir="ltr">${state.next||'—'}</strong><span>${state.next?'أقرب انطلاق منشور في اليوم المختار':'لا يوجد انطلاق متاح في الجدول المختار'}</span></div><span class="chip">${escape(line.name)}</span></div><div class="route-card-body"><div class="route-steps"><div>${escape(from.name)}</div><div>خط ${escape(line.name)} • ${busDirection==='out'?'من كيان':'إلى كيان'}</div><div>${escape(to.name)}</div></div><p>ساعة بدء الرحلة لا تحدد وصولها للعمارة أو نقطة المرور. مكان الركوب والسعة يحتاجان تأكيدًا من المشغل.</p>${line.status!=='published'?'<div class="notice">بيانات هذا الخط جزئية وتحتاج مراجعة آخر إعلان.</div>':''}<div class="route-actions"><button id="show-timetable">المواعيد ومسار الاتجاه</button><button id="save-transit">حفظ الخطة</button></div><a class="bus-directory-link" href="/buses?line=${line.id}&direction=${busDirection}">دليل الباصات الكامل ←</a></div></div>`;$('show-timetable').onclick=()=>tab('bus');$('save-transit').onclick=saveTrip;const coords=[from,to].filter(o=>o.coordinate).map(o=>ll(o.coordinate));if(coords.length)map.fitBounds(coords,{padding:[60,100],maxZoom:16,animate:false});}
