function requestTrip(){if(!from||!to)return;dialog(`<h2>جهّز مشوارك</h2><p>${escape(from.name)} ← ${escape(to.name)}</p><div class="notice">تجربة تجهيز طلب فقط. لا يوجد سائق متصل، ولن يُرسل الطلب أو يُؤكد حجز. وقت وصول العربية غير متاح.</div><div class="request-fields"><label>المعاد<select id="request-when"><option value="now">دلوقتي</option><option value="later">معاد محدد</option></select></label><label id="request-date-label" hidden>التاريخ والوقت بتوقيت القاهرة<input id="request-date" type="datetime-local"></label><label>ملاحظة للالتقاء<textarea id="request-note" maxlength="300" placeholder="مثال: عند مدخل العمارة الرئيسي"></textarea></label></div><button id="save-request" class="primary">حفظ مسودة الطلب على جهازي</button>`);$('request-when').onchange=()=>{$('request-date-label').hidden=$('request-when').value!=='later';};$('save-request').onclick=()=>{const now=cairoParts(),later=$('request-when').value==='later',value=$('request-date').value;if(later&&(!value||value<`${now.iso}T${now.hour}:${now.minute}`)){toast('اختار تاريخًا ووقتًا قادمًا.');return;}const requests=storage.get('jowwa-requests');requests.unshift({id:Date.now(),from,to,when:later?value.replace('T',' '):'دلوقتي',note:$('request-note').value,status:'local-draft-not-sent'});if(storage.set('jowwa-requests',requests.slice(0,40))){$('dialog').close();toast('اتحفظت المسودة على الجهاز. لم تُرسل لسائق.');}};}
function locationError(e){toast(e.code===1?'إذن الموقع مرفوض. تقدر تحدد مكانك يدويًا من الخريطة.':e.code===2?'تعذر تحديد الموقع. اختار عمارتك من البحث.':'تحديد الموقع أخذ وقتًا طويلًا. جرّب تاني أو اختار يدويًا.');}
function plotPosition(pos,{setStart=false}={}){latestPosition=pos;geoLayer.clearLayers();const point=[pos.coords.longitude,pos.coords.latitude],coord=ll(point);L.circle(coord,{radius:pos.coords.accuracy,color:'#4285c6',fillOpacity:.08,weight:1}).addTo(geoLayer);L.circleMarker(coord,{radius:7,color:'#fff',weight:3,fillColor:'#357fc7',fillOpacity:1}).addTo(geoLayer).bindTooltip('موقعك • دقة تقريبية ±'+Math.round(pos.coords.accuracy)+' م');if(setStart){const o={id:'gps-current',name:'موقعي الحالي • ±'+Math.round(pos.coords.accuracy)+' م',coordinate:point};objects.set(o.id,o);setEndpoint('from',o);map.setView(coord,16);toast('تم تحديد مكانك. الدقة التقريبية ±'+Math.round(pos.coords.accuracy)+' متر.');}if(watchId!==null&&$('follow-location'))$('follow-location').textContent='■ إيقاف متابعة موقعي • دقة ±'+Math.round(pos.coords.accuracy)+' م';}
function locate(){if(!navigator.geolocation||!window.isSecureContext){toast('الموقع يحتاج اتصال HTTPS أو تشغيلًا محليًا آمنًا. اختر مكانك يدويًا.');return;}toast('جاري تحديد موقعك…');navigator.geolocation.getCurrentPosition(p=>plotPosition(p,{setStart:true}),locationError,{enableHighAccuracy:true,timeout:15000,maximumAge:15000});}
function followLocation(){if(watchId!==null){navigator.geolocation.clearWatch(watchId);watchId=null;if($('follow-location'))$('follow-location').textContent='◎ متابعة موقعي أثناء الحركة';toast('توقفت متابعة الموقع.');return;}if(!navigator.geolocation||!isSecureContext){toast('متابعة الموقع تحتاج HTTPS وإذن الموقع.');return;}watchId=navigator.geolocation.watchPosition(p=>plotPosition(p),e=>{locationError(e);navigator.geolocation.clearWatch(watchId);watchId=null;},{enableHighAccuracy:true,timeout:15000,maximumAge:5000});toast('الموقع يظهر على جهازك فقط. المتابعة ليست تتبعًا للباص أو السائق.');}
function sources(){dialog(`<h2>خريطة واحدة. مصادر واضحة.</h2><div class="stat-row"><div><b>624</b><span>رقم عمارة من المخططات</span></div><div><b>${data.pois.length}</b><span>خدمات ومعالم محددة الموقع</span></div></div><h3>التغطية الحالية</h3><p>${data.coverage.scope}</p><p>${data.coverage.alignment}</p><p>${data.coverage.routing}</p><h3>المصادر</h3>${data.sources.map(s=>`<div class="source-row"><a href="${escape(s.url)}" target="_blank" rel="noreferrer">${escape(s.title)} ↗</a></div>`).join('')}<h3>دليل الباصات</h3><p><a href="/buses">مراجعة خطوط العباسية والجامعة والحجاز وباقي الخدمات ومصادرها ←</a></p><h3>مصدر باص الجامعة</h3><p>الصورتان منشورتان في 23 مارس 2026. دليل الإدارة بتاريخ 3 نوفمبر 2026 يحيل إليهما. لا نعتبر تاريخ الإحالة تاريخ إصدار جدول جديد، ولا نعرض رسائل الركاب كتتبع حي.</p><h3>كيف نحسب الوقت؟</h3><p>تقدير الحركة: مشي 4.5 كم/س، دراجة 12 كم/س، عربية 20 كم/س، مع نطاق زيادة 30%. هذه افتراضات تخطيطية، بلا زحام حي أو انتظار سائق أو بوابة. الطرق الداخلية تعامل في الاتجاهين طبقًا لوصفك، والطرق الخارجية تحتفظ بالاتجاه المسجل.</p><h3>الخصوصية والتشغيل</h3><p>الموقع بإذنك ويظل في المتصفح؛ المشاوير والمسودات تحفظ محليًا. خلفية OpenStreetMap والخط قد تتصل بالإنترنت. لا يوجد إرسال طلبات أو دفع أو سائقون متصلون في هذه النسخة.</p><a href="data/map.json" download="jowwa-map-data.json">تحميل بيانات الخريطة ↧</a> • <a href="data/bus.json" download="jowwa-bus-data.json">تحميل بيانات الباص ↧</a><p>البيانات المشتقة من OpenStreetMap تحت ODbL؛ مخططات الترقيم مصدرها الملفات التي قدمتها. آخر تجميع: 3 نوفمبر 2026.</p>`);}
function wire(){initSearch();$('route-button').onclick=route;$('swap').onclick=()=>{[from,to]=[to,from];$('from').value=from?.name||'';$('to').value=to?.name||'';invalidate();drawEndpoints();if(from&&to)route();};document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode,true));for(const w of ['from','to'])$('pick-'+w).onclick=()=>startPick(w);$('use-location').onclick=locate;$('map-location').onclick=locate;$('fit-all').onclick=fitAll;$('zoom-in').onclick=()=>map.zoomIn();$('zoom-out').onclick=()=>map.zoomOut();document.querySelectorAll('[data-district]').forEach(b=>b.onclick=()=>{const d=data.districts.find(d=>d.id===b.dataset.district);setSheet('collapsed');fitView(d.polygon,17);});$('layers-button').onclick=()=>$('layers-panel').hidden=!$('layers-panel').hidden;$('layer-buildings').onchange=refreshBuildings;for(const [id,layer] of [['services',serviceLayer],['tiles',tiles],['roads',roadLayer]])$('layer-'+id).onchange=e=>e.target.checked?map.addLayer(layer):map.removeLayer(layer);$('saved-button').onclick=showSaved;$('sources-button').onclick=sources;$('help-map').onclick=sources;$('bus-date').value=cairoParts().iso;$('bus-date').onchange=renderBus;$('day-type').onchange=renderBus;document.querySelectorAll('[data-direction]').forEach(b=>b.onclick=()=>{busDirection=b.dataset.direction;document.querySelectorAll('[data-direction]').forEach(x=>x.classList.toggle('active',x===b));renderBus();});$('example-internal').onclick=()=>{setEndpoint('from',objects.get('yasmin-318'));setEndpoint('to',objects.get('poi-1021898717'));setMode('walk');route();};$('example-cross').onclick=()=>{setEndpoint('from',objects.get('narges-182'));setEndpoint('to',objects.get('yasmin-1'));setMode('car');route();};window.addEventListener('pagehide',()=>{if(watchId!==null)navigator.geolocation.clearWatch(watchId);});}
function setupHome(directory=[]){
 const root=$('home-screen'),back=$('home-back'),rail=root.querySelector('.home-shortcut-rail');
 const journey=mountWelcomeJourney({
  root,stage:$('home-journey-stage'),
  places:[...objects.values()],
  directory,
  busRoutes:transit.routes,
  onRoute:({from:origin,to:destination,mode:travelMode})=>{
   if(!origin?.coordinate||!destination?.coordinate){toast('اختار بداية ووصول معروفين على الخريطة.');return;}
   toggleRound(false);setEndpoint('from',origin);setEndpoint('to',destination);setMode(travelMode);tab('trip');tripWizard.show('ready',true);route();
  },
  onPickMap:which=>{toggleRound(false);tab('trip');tripWizard.show(which,true);startPick(which);},
  onRound:()=>{toggleRound(true);tab('trip');},
  onBus:id=>{
   if(!transit.routes.some(line=>line.id===id)){toast('الخط ده مش موجود في الجدول المنشور.');return;}
   $('bus-line').value=id;tab('bus');renderBus();document.querySelector('.bus-schedule-drawer').open=true;
  },
  onAsk:query=>{assistant?.ask(query);},
  notify:toast
 });
 const open=action=>journey.open(action);
 for(const button of rail.querySelectorAll('[data-home-action]')){
  const entry=welcomeActions.find(item=>item.id===button.dataset.homeAction),symbol=button.querySelector('span');
  if(symbol)symbol.innerHTML=icon(entry?.glyph||'grid');
  button.addEventListener('click',()=>open(button.dataset.homeAction));
 }
 for(const button of root.querySelectorAll('[data-rail-shift]')){
  button.onclick=()=>rail.scrollBy({left:(button.dataset.railShift==='next'?-1:1)*Math.max(rail.clientWidth*.75,240),behavior:'smooth'});
 }
 document.querySelector('.tabs').before(back);
 const showHome=()=>{
  document.body.classList.add('home-mode');root.hidden=false;back.hidden=true;journey.reset();setSheet('expanded');
  requestAnimationFrame(()=>map?.invalidateSize(false));
 };
 back.onclick=()=>{history.pushState({jowwaHome:true},'','/');showHome();};
 window.addEventListener('popstate',()=>{
  const screen=location.hash.slice(1);
  if(['trip','bus','places'].includes(screen))tab(screen);
  else if(!location.search)showHome();
 });
 return journey;
}
async function init(){try{const [a,b]=await Promise.all([fetch('data/map.json'),fetch('data/bus.json')]);if(!a.ok||!b.ok)throw Error('Data unavailable');[data,bus]=await Promise.all([a.json(),b.json()]);transit=await fetch('/data/transit.json').then(r=>{if(!r.ok)throw Error('Transit unavailable');return r.json();});await applyContent(data,transit);$('bus-line').innerHTML=transit.routes.map(r=>`<option value="${r.id}">${escape(r.name)} — ${escape(r.statusLabel)}</option>`).join('');$('bus-line').onchange=renderBus;const directory=await fetch('/data/directory.json').then(r=>r.ok?r.json():[]).catch(()=>[]);for(const p of directory){const parent=data.pois.find(x=>x.id===p.mapId);if(parent&&p.id!==parent.id)data.pois.push({...p,parentId:parent.id,coordinate:parent.coordinate,category:p.mapCategory||(p.category==='مطاعم'?'restaurant':'atm'),status:p.status+' • نقطة الوصول: '+parent.name+'، وليست مدخل الخدمة المؤكد'});else if(parent)Object.assign(parent,{phone:p.phone,status:p.status,source:p.source});}placeCatalog=directoryPlaces(directory,data);buildMap();$('place-search').oninput=renderPlaces;wire();wireUX();tripWizard=mountTripSteps({root:$('direct-builder'),getState:()=>({from,to}),onRoute:route});document.querySelector('.intro').hidden=true;setupRounds();setupNavigation();setupBusJourney();setupAssistant();setupHome(directory);renderBus();renderPlaces();$('loading-screen').hidden=true;document.body.classList.add('home-mode');$('home-screen').hidden=false;setInterval(renderBus,60000);const params=new URLSearchParams(location.search);if(params.get('tab')==='round'||params.has('round')||params.get('rounds')==='1'){toggleRound(true);roundPlanner.restoreLink(params);tab('trip');}if(params.get('tab')==='bus'){if(transit.routes.some(r=>r.id===params.get('line')))$('bus-line').value=params.get('line');tab('bus');renderBus();if(params.get('line'))document.querySelector('.bus-schedule-drawer').open=true;if(params.get('areas')==='1'){showTransitPoints(selectedLine(),busDirection);setSheet('collapsed');}}if(objects.has(params.get('from'))&&objects.has(params.get('to'))){setEndpoint('from',objects.get(params.get('from')));setEndpoint('to',objects.get(params.get('to')));setMode(['walk','bike','car','bus'].includes(params.get('mode'))?params.get('mode'):'walk');tab('trip');route();}else if(objects.has(params.get('to'))){const selected=objects.get(params.get('to'));setEndpoint('to',selected);tab('trip');tripWizard.show('from',true);if(selected.coordinate)fitView([selected.coordinate],17);toast('اختار بداية المشوار للوصول للمكان.');}window.jowwa={data,bus,transit,map,getState:()=>({from,to,mode,lastRoute}),select:(f,t,m='walk')=>{setEndpoint('from',objects.get(f));setEndpoint('to',objects.get(t));setMode(m);route();}};}catch(e){console.error(e);$('loading-screen').innerHTML='<strong>تعذر تحميل الخريطة</strong><p>تأكد من الاتصال وحاول مرة تانية.</p><button id=retry-load>إعادة المحاولة</button>';$('retry-load').onclick=()=>location.reload();$('coverage-count').textContent='تعذر تحميل البيانات';$('route-result').innerHTML='<div class="error-state">تعذر فتح بيانات الخريطة. أعد تحميل الصفحة أو تأكد من تشغيل التطبيق.</div>';}}

function toggleRound(active){if(navigation?.isActive())navigation.stop({silent:true});roundActive=active;cancelPick();routeToken++;lastRoute=null;routeLayer.clearLayers();endpointLayer.clearLayers();$('route-summary').hidden=true;document.body.classList.remove('has-route');$('round-overview').hidden=true;$('direct-builder').hidden=active;$('round-builder').hidden=!active;for(const [id,on] of [['direct-trip',!active],['round-trip',active]]){$(id).classList.toggle('active',on);$(id).setAttribute('aria-pressed',String(on));}if(active)roundPlanner.activate(from);else{roundPlanner.deactivate();drawEndpoints();}setSheet('expanded');}
function setupRounds(){
 const overview=document.createElement('div');overview.id='round-overview';overview.className='round-overview';overview.hidden=true;document.querySelector('.map-area').append(overview);
 const clear=()=>{routeLayer.clearLayers();endpointLayer.clearLayers();overview.hidden=true;};
 const draw=({points,result,mode:travelMode})=>{if(!roundActive)return;clear();for(const [i,leg] of result.legs.entries()){L.polyline(leg.points.map(ll),{color:'#fff',weight:9}).addTo(routeLayer);L.polyline(leg.points.map(ll),{color:['#245d45','#547435','#386b8c','#9a7041'][i%4],weight:5}).addTo(routeLayer);for(const [a,b] of [[points[leg.from].coordinate,leg.snapStart],[leg.snapEnd,points[leg.to].coordinate]])L.polyline([ll(a),ll(b)],{color:'#a77843',weight:3,dashArray:'4 6'}).addTo(routeLayer);}const order=result.order.slice(0,result.order.at(-1)===0?-1:undefined);order.forEach((i,n)=>L.marker(ll(points[i].coordinate),{icon:L.divIcon({className:'round-pin '+(n===0?'start':''),html:n===0?'ب':n,iconSize:[31,31]})}).addTo(endpointLayer).bindPopup(`<b>${escape(points[i].name)}</b><p>${n===0?'بداية الراوند':'المحطة '+n}</p>`));const minutes=estimateMinutes(result.distance,travelMode);overview.innerHTML=`<b>راوند ${points.length-1} محطات • ${minutes}–${Math.ceil(minutes*1.3)} دقيقة</b><small>${(result.distance/1000).toFixed(2)} كم • وقت حركة تقديري</small><button id="edit-round-overview">غيّر البداية أو المحطات ↑</button>`;overview.hidden=false;$('edit-round-overview').onclick=()=>{tab('trip');setSheet('expanded');};$('sheet-title').textContent='الراوند جاهز';$('sheet-subtitle').textContent=`${points.length-1} محطات • ${minutes}–${Math.ceil(minutes*1.3)} دقيقة`;};
 roundPlanner=mountRoundPlanner({root:$('round-builder'),places:[...objects.values()],roads:data.roads,notify:toast,sync:createRoundSync({notify:toast}),getNavigationContext:()=>navigation?.planningContext(),onLiveUpdate:payload=>{if(payload.error){navigation?.stop();toast(payload.error==='permission'?'الراوند يحتاج موافقة المنفّذ على التحديث.':'مفيش وقفات متبقية.');}else navigation?.updateRemaining(payload);},onClear:clear,onDraw:draw,onNavigate:payload=>navigation.start({origin:payload.points[0],targets:payload.result.order.slice(1).map(i=>payload.points[i]),mode:payload.mode}),onShow:payload=>{draw(payload);setSheet('collapsed');fitView([...payload.points.map(p=>p.coordinate),...payload.result.legs.flatMap(l=>l.points)]);},onPick:accept=>{cancelPick();roundPick=accept;setSheet('collapsed');$('map-pick-hint').hidden=false;$('map-pick-hint').innerHTML='اختار نقطة الراوند على الخريطة <button id="cancel-pick">إلغاء</button>';$('cancel-pick').onclick=cancelPick;document.querySelector('.map-area').classList.add('picking');}});
 $('direct-trip').onclick=()=>toggleRound(false);$('round-trip').onclick=()=>toggleRound(true);
}

function syncFields(){for(const which of ['from','to'])$('clear-'+which).hidden=!$(which).value;const b=$('route-button');if(!from||!to)b.title='اختار البداية والوصول أولًا';else b.title='حساب الطريق بين النقطتين';tripWizard?.refresh();}

function setSheet(next){sheet=next;document.body.classList.toggle('sheet-collapsed',next==='collapsed');document.body.classList.toggle('sheet-expanded',next==='expanded');$('sheet-toggle').setAttribute('aria-expanded',next==='expanded');$('sheet-toggle').querySelector('span').textContent=next==='expanded'?'عرض الخريطة ↓':'اسحب أو اضغط';if(next==='collapsed')document.querySelector('.sidebar').scrollTop=0;}

function fitView(points,maxZoom=17){if(!points.length)return;map.stop();if(isMobile()){const h=map.getSize().y,covered=sheet==='collapsed'?112:Math.min(innerHeight*.5,h*.5);map.fitBounds(points.map(ll),{paddingTopLeft:[46,128],paddingBottomRight:[24,Math.min(covered+85,h-180)],maxZoom,animate:false});}else map.fitBounds(points.map(ll),{padding:[65,100],maxZoom,animate:false});}

function buildingPicker(which){
 let district=(which==='from'?from:to)?.district||from?.district||'yasmin';
 const placeFor=n=>data.buildings.find(p=>p.district===district&&Number(p.number)===n);
 const chooseDistrict=()=>{dialog(`<div class="quick-picker round-screen-enter"><h2>أي كمبوند؟</h2><div class="picker-districts"><button data-picker-district="yasmin">الياسمين</button><button data-picker-district="narges">النرجس</button></div></div>`);document.querySelectorAll('[data-picker-district]').forEach(b=>b.onclick=()=>{district=b.dataset.pickerDistrict;chooseNumber();});};
 const chooseNumber=()=>{dialog(`<div class="quick-picker round-screen-enter"><button id="picker-back" aria-label="الكمبوند السابق">←</button><h2>رقم العمارة إيه؟</h2><p>${district==='yasmin'?'الياسمين':'النرجس'} • ${which==='from'?'البداية':'الوصول'}</p><div class="picker-number"><label for="building-number">رقم العمارة</label><input id="building-number" inputmode="numeric" pattern="[0-9٠-٩]*" maxlength="5" placeholder="مثال: 194" autocomplete="off"></div><div class="picker-hints">${[1,84,194].filter(n=>placeFor(n)).map(n=>`<button data-picker-number="${n}">${n}</button>`).join('')}</div><div id="picker-preview" class="picker-preview" aria-live="polite">الأرقام من مخطط الترقيم المتاح.</div><button id="picker-go" class="primary" disabled>اختار العمارة ←</button></div>`);
 const update=()=>{const raw=normalize($('building-number').value),place=placeFor(Number(raw));$('picker-go').disabled=!raw||!/^\d+$/.test(raw)||!place;$('picker-preview').textContent=!raw?'اكتب الرقم أو اختار من الأمثلة.':place?place.name+' • الموقع تقريبي':'الرقم غير موجود في المخطط المتاح لهذا الكمبوند.';$('picker-preview').classList.toggle('picker-error',!!raw&&!place);};
 $('picker-back').onclick=chooseDistrict;document.querySelectorAll('[data-picker-number]').forEach(b=>b.onclick=()=>{$('building-number').value=b.dataset.pickerNumber;update();});$('building-number').oninput=update;$('building-number').onkeydown=e=>{if(e.key==='Enter'&&!$('picker-go').disabled)$('picker-go').click();};$('picker-go').onclick=()=>{const place=placeFor(Number(normalize($('building-number').value)));if(!place)return;$('dialog').close();setEndpoint(which,place,{auto:true,fly:true});if(!from||!to)setSheet('expanded');};update();};
 chooseDistrict();
}

function wireUX(){
 syncFields();for(const which of ['from','to']){$('building-'+which).onclick=()=>buildingPicker(which);$('clear-'+which).onclick=()=>{if(which==='from')from=null;else to=null;$(which).value='';invalidate();drawEndpoints();$(which).focus();};}
 $('sheet-toggle').onclick=()=>setSheet(sheet==='expanded'?'collapsed':'expanded');$('edit-trip').onclick=()=>{tab('trip');setSheet('expanded');document.querySelector('.sidebar').scrollTop=0;};
 let startY=null,dragged=false;const handle=$('sheet-toggle');handle.addEventListener('pointerdown',e=>{startY=e.clientY;dragged=false;handle.setPointerCapture(e.pointerId);});handle.addEventListener('pointerup',e=>{if(startY===null)return;const delta=e.clientY-startY;if(Math.abs(delta)>35){dragged=true;setSheet(delta>0?'collapsed':'expanded');}startY=null;});handle.addEventListener('click',e=>{if(dragged){e.stopImmediatePropagation();dragged=false;}},true);
 document.querySelector('.sidebar').addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('dialog').open){cancelPick();setSheet('collapsed');}});
 const connectivity=()=>{$('connection-status').hidden=navigator.onLine;};window.addEventListener('online',connectivity);window.addEventListener('offline',connectivity);connectivity();
 window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('install-app').hidden=false;});$('install-app').onclick=async()=>{if(!installPrompt)return;await installPrompt.prompt();const choice=await installPrompt.userChoice;if(choice.outcome==='accepted')toast('اتضاف جوه للموبايل.');installPrompt=null;$('install-app').hidden=true;};window.addEventListener('appinstalled',()=>{$('install-app').hidden=true;});
 if('serviceWorker' in navigator&&isSecureContext)navigator.serviceWorker.register('/sw.js').catch(()=>{});
 const pickerDates=document.createElement('div');pickerDates.className='bus-date-actions';pickerDates.innerHTML='<button id="bus-today">النهارده</button><button id="bus-tomorrow">بكرة</button>';$('bus-content').before(pickerDates);
 for(const [id,days] of [['bus-today',0],['bus-tomorrow',1]])$(id).onclick=()=>{const d=new Date(cairoParts().iso+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+days);$('bus-date').value=d.toISOString().slice(0,10);$('day-type').value='auto';renderBus();};
 $('route-button').disabled=false;
}
init();

function setupNavigation(){const root=document.createElement('section');root.id='navigation-ui';root.setAttribute('aria-label','متابعة المشوار');document.querySelector('.map-area').append(root);navigation=createNavigation({map,roads:data.roads,places:[...objects.values()],root,notify:toast,onStart:()=>{if(watchId!==null){navigator.geolocation.clearWatch(watchId);watchId=null;}cancelPick();routeLayer.clearLayers();endpointLayer.clearLayers();setSheet('collapsed');},onStop:()=>{if(roundActive)roundPlanner.activate(from);else if(lastRoute){routeLayer.clearLayers();L.polyline(lastRoute.points.map(ll),{color:'#245d45',weight:5}).addTo(routeLayer);drawEndpoints();}map.invalidateSize();}});}

function setupBusJourney(){const root=document.createElement('div');root.id='bus-journey';const panel=$('bus-panel'),drawer=document.createElement('details');drawer.className='bus-schedule-drawer';drawer.innerHTML='<summary>كل المواعيد والتفاصيل</summary>';for(const child of [...panel.children])if(!child.classList.contains('bus-heading'))drawer.append(child);panel.append(root,drawer);if(new URLSearchParams(location.search).has('line'))drawer.open=true;const css=document.createElement('link');css.rel='stylesheet';css.href='/bus-journey.css';document.head.append(css);mountBusJourney({root,transit,roads:data.roads,places:[...objects.values()],getOrigin:()=>from,onRouteTo:(target,origin)=>{toggleRound(false);if(origin)setEndpoint('from',origin);setEndpoint('to',target);setMode('walk');tab('trip');route();},toast});}

function setupAssistant(){
 const root=document.createElement('div');root.id='jowwa-assistant';$('home-ai').append(root);const css=document.createElement('link');css.rel='stylesheet';css.href='/assistant.css';document.head.append(css);
 const askOrigin=()=>{toggleRound(false);tab('trip');tripWizard.show('from',true);};
 assistant=mountAssistant({root,openOnMount:false,onPrepareRound:ids=>{toggleRound(true);if(!roundPlanner.prepareStops(ids)){toast('تعذر تجهيز هذه النقاط؛ اختار الأماكن من الخريطة.');return;}tab('trip');setSheet('expanded');toast('الوقفات جاهزة كمسودة؛ اختار البداية وراجع المواعيد.');},onPrepareRoute:ids=>{if(!Array.isArray(ids)||ids.length!==2||ids[0]===ids[1]||ids.some(id=>!objects.get(id)?.coordinate||objects.get(id).external)){toast('اختار نقطتين معروفتين على الخريطة.');return;}toggleRound(false);setEndpoint('from',objects.get(ids[0]));setEndpoint('to',objects.get(ids[1]));setMode('walk');tab('trip');tripWizard.show('mode',true);},onPlace:id=>{const place=objects.get(id);if(!place){toast('المكان موجود في الدليل؛ نقطة الوصول لم تتأكد على الخريطة بعد.');return;}toggleRound(false);setEndpoint('to',place);setMode('walk');askOrigin();},onBus:id=>{if(!transit.routes.some(r=>r.id===id)){toast('الخط غير متاح حاليًا.');return;}$('bus-line').value=id;document.querySelector('.bus-schedule-drawer').open=true;tab('bus');renderBus();},onAskOrigin:askOrigin,toast});
 root.querySelector('details').addEventListener('toggle',event=>{document.querySelector('.sidebar').classList.toggle('assistant-open',event.currentTarget.open);if(event.currentTarget.open)setSheet('expanded');});
}
